package com.yeyamo_mobile.api.graph_service.application;
import org.springframework.core.task.TaskExecutor;import org.springframework.data.neo4j.core.Neo4jClient;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.stereotype.Service;import java.time.*;import java.util.*;
@Service public class GraphRebuildService{private final Neo4jClient neo;private final KafkaTemplate<String,String> kafka;private final TaskExecutor executor;public GraphRebuildService(Neo4jClient n,KafkaTemplate<String,String> k,TaskExecutor e){neo=n;kafka=k;executor=e;}public UUID start(String actor){UUID id=UUID.randomUUID();neo.query("CREATE (j:GraphRebuildJob {id:$id,status:'PENDING',actorId:$actor,createdAt:$at})").bindAll(Map.of("id",id.toString(),"actor",actor,"at",Instant.now().toString())).run();executor.execute(()->rebuild(id));return id;}public void rebuild(UUID id){try{neo.query("MATCH (j:GraphRebuildJob {id:$id}) SET j.status='RUNNING',j.startedAt=$at").bindAll(Map.of("id",id.toString(),"at",Instant.now().toString())).run();neo.query("MATCH (n) WHERE NOT n:GraphRebuildJob DETACH DELETE n").run();String command="{\"eventId\":\""+UUID.randomUUID()+"\",\"eventType\":\"CultureGraphRebuildRequested\",\"eventVersion\":1,\"producer\":\"graph-service\",\"occurredAt\":\""+Instant.now()+"\",\"payload\":{\"jobId\":\""+id+"\"}}";kafka.send("graph.commands",id.toString(),command);neo.query("MATCH (j:GraphRebuildJob {id:$id}) SET j.status='AWAITING_SOURCE_REPLAY',j.updatedAt=$at").bindAll(Map.of("id",id.toString(),"at",Instant.now().toString())).run();}catch(Exception e){neo.query("MATCH (j:GraphRebuildJob {id:$id}) SET j.status='FAILED',j.updatedAt=$at").bindAll(Map.of("id",id.toString(),"at",Instant.now().toString())).run();}}}
